import type { State } from "./types.js";

const cell = (text: string) => text.replace(/\|/g, "\\|").replace(/\r?\n/g, " ");

/** board.md is generated from state.json; never edited by hand. */
export function renderBoard(state: State): string {
  const { run } = state;
  const lines = [
    "# Board",
    "",
    "<!-- Generated by sa from .superagent/state.json. Do not edit by hand. -->",
    "",
    `Run ${run.id} · max ${run.maxWorkers} workers · budget ${run.budgetTokens.toLocaleString("en-US")} tokens`,
    "",
  ];

  const ids = Object.keys(state.tickets).sort();
  if (ids.length === 0) {
    lines.push("_No tickets yet._", "");
    return lines.join("\n");
  }

  lines.push("| ID | Title | Status | Mode | Runs | PR |", "| --- | --- | --- | --- | --- | --- |");
  for (const id of ids) {
    const t = state.tickets[id]!;
    const runs = t.dependsOn.length ? `after ${t.dependsOn.join(", ")}` : "alone";
    lines.push(`| ${id} | ${cell(t.title)} | ${t.status} | ${t.mode} | ${runs} | ${t.pr ? cell(t.pr) : "–"} |`);
  }
  lines.push("");
  return lines.join("\n");
}
